// Mockup-angle photo sprite as data URIs (text-safe for GitHub Pages).
window.ROACH_EMBED = {
  'roach.webp': 'data:image/webp;base64,',
  'roach-mini.webp': 'data:image/webp;base64,'
};

(function () {
  var map = window.ROACH_EMBED;
  if (!map) return;
  document.querySelectorAll('img').forEach(function (img) {
    var name = (img.getAttribute('src') || '').split('/').pop();
    if (map[name]) img.src = map[name];
  });
})();
